	return b.graph.client.update(b.data)
}

// UserDeleteOne builds the delete of one `users` row. Start one with
// `Graph.users().delete_one(node)` or `delete_one_id(id)`.
pub struct UserDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q UserQuery) delete_one(node UserNode) UserDeleteOne {
	return q.delete_one_id(node.user.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q UserQuery) delete_one_id(id i64) UserDeleteOne {
	return UserDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:      .delete_one
			table:   'users'
			row_key: id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b UserDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'users'
		}
	}
}

// UserDelete builds the delete of the `users` rows that match its conditions.
// Start one with `Graph.users().delete()`.
pub struct UserDelete {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete starts the delete of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q UserQuery) delete() UserDelete {
	return UserDelete{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete
			table: 'users'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b UserDelete) where(conds ...load.Cond) UserDelete {
	return UserDelete{
		...b
		data: b.data.with_conds(conds)
	}
}

