// users_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) users_by_keys(keys []string) ![]UserNode {
	// as stored: no privacy rule or interceptor hides a row just written
	rows := Graph{
		client: g.client.bypass()
	}.users().where(load.in_keys('id', keys, .i64)).all()!
	mut by_key := map[string]UserNode{}
	for row in rows {
		by_key[row.user.id.str()] = row
	}
	mut found := []UserNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'users'
			}
		}
	}
	return found
}

// CreateUserInput is what a create of a `users` row sets, as the GraphQL input
// `CreateUserInput` gives it: `none` and empty lists leave things as
// they are.
pub struct CreateUserInput {
pub mut:
	name     ?string
	email    ?string
	password ?string
	admin    ?bool
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b UserCreate) set_input(input CreateUserInput) UserCreate {
	mut next := b
	if v := input.name {
		next = next.set_name(v)
	}
	if v := input.email {
		next = next.set_email(v)
	}
	if v := input.password {
		next = next.set_password(v)
	}
	if v := input.admin {
		next = next.set_admin(v)
	}
	return next
}

